<?php
require_once __DIR__ . '/includes/bootstrap.php'; require_login();
$stmt = $pdo->prepare('SELECT * FROM orders WHERE user_id = ? ORDER BY created_at DESC'); $stmt->execute([current_user()['id']]); $orders = $stmt->fetchAll();
$title = 'Your orders — Rally'; require __DIR__ . '/includes/header.php';
?>
<section class="section-wrap orders-page"><div class="page-heading"><span class="eyebrow">YOUR RALLY ACCOUNT</span><h1>Order history.</h1></div><?php if (isset($_GET['placed'])): ?><div class="success-banner">Order #<?= (int) $_GET['placed'] ?> is in motion. Thanks for rallying with us.</div><?php endif; ?><?php if (!$orders): ?><div class="empty-state"><p>No orders yet. Your next favorite is waiting.</p><a class="button button-dark" href="<?= e(app_url('#shop')) ?>">Shop the collection <span>↗</span></a></div><?php else: ?><?php foreach ($orders as $order): ?><article class="order-card"><div class="order-card-head"><div><span class="eyebrow">ORDER #<?= (int) $order['id'] ?></span><p><?= e(date('M j, Y', strtotime($order['created_at']))) ?></p></div><span class="status-pill"><?= e(ucfirst($order['status'])) ?></span><strong><?= money($order['total']) ?></strong></div><?php $lineStmt = $pdo->prepare('SELECT product_name, unit_price, quantity FROM order_items WHERE order_id = ?'); $lineStmt->execute([$order['id']]); ?><div class="order-lines"><?php foreach ($lineStmt->fetchAll() as $line): ?><span><?= e($line['product_name']) ?> × <?= (int) $line['quantity'] ?> <b><?= money((float) $line['unit_price'] * (int) $line['quantity']) ?></b></span><?php endforeach; ?></div><small>Delivery to <?= e($order['recipient_name']) ?> · <?= e($order['city']) ?> · <?= e($order['postal_code']) ?></small></article><?php endforeach; ?><?php endif; ?></section>
<?php require __DIR__ . '/includes/footer.php'; ?>
